import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  it('passes valid input through to the executor including undeclared extra properties', async () => {
    const registry = new ToolRegistry();
    let captured: Record<string, unknown> | undefined;
    registry.register(
      {name: 'w', description: '', inputSchema: {type: 'object', properties: {x: {type: 'string'}}, required: ['x']}},
      async input => {
        captured = input;
        return 'ok';
      }
    );
    const payload = {x: 'hello', extra: 'bonus'};
    await registry.execute('w', payload);
    expect({captured}).toEqual({captured: payload});
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('uses the compiled static schema even after the source definition object is mutated', async () => {
    const def: ToolDefinition = {
      name: 'static_tool',
      description: '',
      inputSchema: {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
    };
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(def, async () => {
      executorCalls += 1;
      return 'ok';
    });
    def.inputSchema = {type: 'object'};
    const response = await registry.execute('static_tool', {});
    expect({
      executorCalls,
      rejectedForCity: response.result.includes('city') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      rejectedForCity: true,
    });
  });

  it('validates against the schema returned by the function source at each call, not a prior call schema', async () => {
    const registry = new ToolRegistry();
    let requiresY = true;
    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: '',
        inputSchema: requiresY
          ? {type: 'object', properties: {y: {type: 'string'}}, required: ['y']}
          : {type: 'object'},
      }),
      async () => 'ok'
    );
    const response1 = await registry.execute('dynamic_tool', {});
    requiresY = false;
    const response2 = await registry.execute('dynamic_tool', {});
    expect({
      firstCallRejectedForY: response1.result.includes('y') && /required/i.test(response1.result),
      secondCallPassed: response2.result,
    }).toEqual({
      firstCallRejectedForY: true,
      secondCallPassed: 'ok',
    });
  });
});

